import{_ as d,o as a,c as e,a4 as r}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"ZTE 4G LTE 随身 WiFi 探索记录","description":"","frontmatter":{"title":"ZTE 4G LTE 随身 WiFi 探索记录","date":"2026-06-30T00:00:00.000Z"},"headers":[],"relativePath":"posts/随身WiFi设备记录.md","filePath":"posts/随身WiFi设备记录.md"}'),i={name:"posts/随身WiFi设备记录.md"};function o(l,t,h,s,n,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="zte-4g-lte-随身-wifi-探索记录" tabindex="-1">ZTE 4G LTE 随身 WiFi 探索记录 <a class="header-anchor" href="#zte-4g-lte-随身-wifi-探索记录" aria-label="Permalink to &quot;ZTE 4G LTE 随身 WiFi 探索记录&quot;">​</a></h1><blockquote><p>设备标识: Punguin_Uz901<br> 硬件: 展讯 TSP ZX297520V3<br> CPU: ARMv7 Cortex-A53 (单核)<br> RAM: 21MB (+ 12MB zram)<br> Flash: 8MB (6个 MTD 分区)<br> 系统: 精简嵌入式 Linux (Linux 3.4.110 RT)<br> 连接方式: ADB (USB)</p></blockquote><hr><h2 id="设备定位" tabindex="-1">设备定位 <a class="header-anchor" href="#设备定位" aria-label="Permalink to &quot;设备定位&quot;">​</a></h2><p>这是一台 <strong>ZTE 4G LTE WiFi 热点棒</strong>（随身 WiFi / MIFI），不是 Android 设备。拆开就是一个小 U 盘大小的 4G 上网卡 + WiFi 热点。</p><h3 id="运行中的服务" tabindex="-1">运行中的服务 <a class="header-anchor" href="#运行中的服务" aria-label="Permalink to &quot;运行中的服务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>进程</th><th>用途</th></tr></thead><tbody><tr><td><code>zte_ufi</code></td><td>4G 拨号主程序</td></tr><tr><td><code>goahead</code></td><td>Web 管理界面 (端口 80)</td></tr><tr><td><code>hostapd</code></td><td>WiFi 热点</td></tr><tr><td><code>dnsmasq</code></td><td>DHCP + DNS (端口 53)</td></tr><tr><td><code>udhcpd</code></td><td>DHCP 服务器</td></tr><tr><td><code>at_server</code></td><td>AT 指令服务 (端口 9090)</td></tr><tr><td><code>adbd</code></td><td>ADB 调试接口 (端口 5037)</td></tr><tr><td><code>/bin/qrzl_app</code></td><td>未知应用</td></tr></tbody></table><h3 id="分区布局" tabindex="-1">分区布局 <a class="header-anchor" href="#分区布局" aria-label="Permalink to &quot;分区布局&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分区</th><th>大小</th><th>用途</th></tr></thead><tbody><tr><td>mtd0 (zloader)</td><td>32KB</td><td>引导加载器</td></tr><tr><td>mtd1 (nvrofs)</td><td>224KB</td><td>网络配置 (只读)</td></tr><tr><td>mtd2 (uboot)</td><td>160KB</td><td>U-Boot</td></tr><tr><td>mtd3 (imagefs)</td><td>4.2MB</td><td>固件镜像 (只读 jffs2)</td></tr><tr><td>mtd4 (rootfs)</td><td>3.1MB</td><td>根文件系统 (只读 squashfs)</td></tr><tr><td>mtd5 (userdata)</td><td>384KB</td><td>用户数据 (jffs2, 240KB 空闲)</td></tr></tbody></table><h3 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h3><ul><li>4G 网: <code>wan1</code> — IP 10.124.131.241 (运营商 CGNAT，非公网)</li><li>WiFi 网: <code>br0</code> — IP 192.168.100.1/24 (热点局域网)</li></ul><hr><h2 id="能力评估" tabindex="-1">能力评估 <a class="header-anchor" href="#能力评估" aria-label="Permalink to &quot;能力评估&quot;">​</a></h2><h3 id="能做" tabindex="-1">能做 <a class="header-anchor" href="#能做" aria-label="Permalink to &quot;能做&quot;">​</a></h3><ul><li>通过 ADB 推送文件到 <code>/tmp</code> 或 <code>/mnt/userdata</code></li><li>运行静态编译的 ARMv7 二进制文件</li><li>可安装一个纯 HTTP 转发代理（C + musl 编译，~15-30KB）</li><li>可建立出站连接（TCP/UDP）</li></ul><h3 id="不能做" tabindex="-1">不能做 <a class="header-anchor" href="#不能做" aria-label="Permalink to &quot;不能做&quot;">​</a></h3><ul><li>没有 ARM 交叉编译器（需要自行搭建）</li><li>不支持 TLS/SSL（openssl 太大，装不下）</li><li>没有 USB gadget 驱动，无法改变 USB 模式</li><li>不支持 Python/Lua/PHP 等脚本语言</li><li>无法直接暴露端口到公网（CGNAT）</li><li>运行中内容无法持久化到重启后（/tmp 是 tmpfs）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>空闲 RAM</td><td>~6MB</td></tr><tr><td>持久化空间</td><td>240KB (jffs2)</td></tr><tr><td>CPU</td><td>单核 Cortex-A53，无 FPU</td></tr><tr><td>Libc</td><td>uclibc (非 glibc)</td></tr><tr><td>Shell</td><td>busybox ash (功能有限)</td></tr></tbody></table><hr><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>用来跑一个小型 HTTP 转发代理理论上可行（编译一个 15-30KB 的纯静态二进制），但有 TLS 指纹识别的方案塞不下（最低 500KB+）。由于无公网 IP，只能做出站连接，适合 tunnel/frp 类工具，不适合直接对外提供服务。</p>',22)])])}const f=d(i,[["render",o]]);export{u as __pageData,f as default};
